import{_ as t,o as s,c as a,a2 as n}from"./chunks/framework.7R1OEGYz.js";const p=JSON.parse('{"title":"Administration","description":"","frontmatter":{},"headers":[],"relativePath":"admin.md","filePath":"admin.md","lastUpdated":1794051234000}'),r={name:"admin.md"};function i(o,e,d,l,h,c){return s(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="administration" tabindex="-1">Administration <a class="header-anchor" href="#administration" aria-label="Permalink to &quot;Administration&quot;">​</a></h1><p>Admins manage users and roles, the organisation&#39;s MCP catalog, the Enterprise licence and, with a licence, usage limits, group roles, allowed agents and skill publishing. All of it lives in the <strong>ADMIN</strong> section of <strong>Settings</strong>, which only admins see.</p><p><strong>Edition:</strong> Community (admin roles, Org MCP catalog, licence entry) · Enterprise (seats, usage limits, group roles, allowed agents, skill publishing, billing) · <strong>Who:</strong> admin, operator</p><h2 id="who-is-an-admin" tabindex="-1">Who is an admin <a class="header-anchor" href="#who-is-an-admin" aria-label="Permalink to &quot;Who is an admin&quot;">​</a></h2><p>The first matching rule decides:</p><table tabindex="0"><thead><tr><th>#</th><th>Source</th><th>Result</th><th>Changeable in the UI</th></tr></thead><tbody><tr><td>1</td><td>The username is listed in the chart value <code>ee.admins</code></td><td>admin</td><td>No: a break-glass admin</td></tr><tr><td>2</td><td>A role set for the user under <strong>Users &amp; seats → Admins &amp; roles</strong></td><td>admin or user</td><td>Yes</td></tr><tr><td>3</td><td>Membership in an OIDC group mapped to <strong>admin</strong> (Enterprise)</td><td>admin</td><td>Yes, under <strong>Usage limits &amp; groups</strong></td></tr><tr><td>4</td><td>Membership in a group mapped to <strong>user</strong> (Enterprise)</td><td>user</td><td>Label only</td></tr><tr><td>5</td><td>Otherwise</td><td>user</td><td>—</td></tr></tbody></table><ul><li><strong>Nobody is an admin by default.</strong> With OIDC, name the first admin in the chart value <code>ee.admins</code> (see below); after that, admins can promote others in the UI. Until then nobody can open the admin area, and every signed-in user sees a notice: <em>No administrator is designated</em>, with the value to set for their own username. <code>helm install</code> and <code>helm upgrade</code> print the same hint, and the backend logs it at startup.</li><li><strong>API key:</strong> on an install without OIDC, the user the API key acts as is always an admin.</li><li><strong><code>ee.admins</code></strong> takes comma-separated usernames (the <code>preferred_username</code> claim). These accounts cannot be demoted in the UI, so they still work if the role settings are edited into a corner. Listed admins who have not signed in yet are shown too.</li><li><strong>A per-user role wins over groups.</strong> You can demote one member of an admin group, or promote one person without creating a group for them.</li><li><strong>Admin wins over user within groups.</strong> Someone in both an admin group and a user group is an admin. A <strong>user</strong> mapping only labels; it never restricts who can sign in.</li><li><strong>The last admin cannot be removed</strong>, yourself included.</li></ul><p>Role changes apply at the user&#39;s next request on every backend replica, without a redeploy. Roles can be set only for users who have signed in at least once. <strong>Recent role changes</strong> shows who changed what, and when.</p><h3 id="designating-the-first-admin" tabindex="-1">Designating the first admin <a class="header-anchor" href="#designating-the-first-admin" aria-label="Permalink to &quot;Designating the first admin&quot;">​</a></h3><p>Set your OIDC username (the <code>preferred_username</code> claim) and upgrade the release:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">helm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upgrade</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub/open-agenthub</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --reset-then-reuse-values</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --set-string</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ee.admins=alice</span></span></code></pre></div><p>Several names are comma-separated. Accounts listed there stay admins whatever is set in the UI.</p><p><strong>Upgrading from 1.18 or earlier:</strong> older releases made every signed-in user an admin while no admin was designated. That no longer happens. Admins you designated in <code>ee.admins</code>, under <strong>Admins &amp; roles</strong>, or through an admin group keep their rights. If you never designated one, nobody is an admin after the upgrade until you set <code>ee.admins</code>.</p><h3 id="switching-from-the-api-key-to-oidc" tabindex="-1">Switching from the API key to OIDC <a class="header-anchor" href="#switching-from-the-api-key-to-oidc" aria-label="Permalink to &quot;Switching from the API key to OIDC&quot;">​</a></h3><p>Data belongs to a username. Everything created with the API key — sessions, credentials, projects — belongs to the key&#39;s user (<code>admin</code> unless you set <code>auth.apiKey.owner</code>; <code>dev</code> on installs from before the API key). After a switch to OIDC, that data is visible to the identity-provider user with the same username.</p><p><strong>Before you switch</strong>, do one of these:</p><ul><li>Choose a key user name that nobody can register at your identity provider (<code>auth.apiKey.owner</code>) — ideally when you install, before any data exists.</li><li>Or move or delete the data that should not carry over.</li></ul><p>After the switch:</p><ul><li>Set <code>ee.admins</code> to your OIDC username. The key&#39;s user name does not make anyone an admin under OIDC: it can only be made one through <code>ee.admins</code>, not under <strong>Admins &amp; roles</strong> or through a group.</li><li>While data is still stored under that name, admins see a notice — <em>Data from API-key mode is under the name …</em> — with the number of sessions and projects, and the backend logs it at startup.</li><li>With a licence, the key&#39;s user keeps a seat under <strong>Users &amp; seats</strong>. Revoke it there once you no longer need its data.</li></ul><h2 id="admin-tabs-in-settings" tabindex="-1">Admin tabs in Settings <a class="header-anchor" href="#admin-tabs-in-settings" aria-label="Permalink to &quot;Admin tabs in Settings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tab</th><th>What it contains</th><th>Edition</th></tr></thead><tbody><tr><td><strong>Users &amp; seats</strong></td><td>Everyone who has signed in. With a licence, each user&#39;s seat (<strong>licensed</strong> / <strong>no seat</strong>) and the seat count; the <strong>Admins &amp; roles</strong> card with role, source and change history.</td><td>Roles: Community. Seats: Enterprise</td></tr><tr><td><strong>Org MCP catalog</strong></td><td>MCP servers offered to the whole organisation. See <a href="/docs/mcp-servers">MCP servers</a>.</td><td>Community</td></tr><tr><td><strong>Usage limits &amp; groups</strong></td><td>Organisation-wide API budgets, OIDC groups and their roles, allowed agents.</td><td>Enterprise</td></tr><tr><td><strong>Skill publishing</strong></td><td><strong>User skill publishing</strong>: whether non-admin users may publish their own skills to everyone. See <a href="/docs/skills">Skills</a>.</td><td>Enterprise</td></tr><tr><td><strong>Billing &amp; invoices</strong></td><td>A link to the billing portal for subscription, invoices and cancellation.</td><td>Enterprise</td></tr><tr><td><strong>License</strong></td><td>Enter, view and remove the Enterprise licence.</td><td>Community</td></tr></tbody></table><p>Without a licence, an Enterprise pane shows <strong>Enterprise feature</strong> with a link to activate one.</p><h2 id="entering-a-licence" tabindex="-1">Entering a licence <a class="header-anchor" href="#entering-a-licence" aria-label="Permalink to &quot;Entering a licence&quot;">​</a></h2><ol><li>Open <strong>Settings → License</strong>.</li><li>Paste the token into <strong>License token</strong> and click <strong>Activate</strong>.</li><li>The card shows plan, organisation, seats included and renewal or end date.</li></ol><p>The licence is verified offline and stored in the database, not in the chart, so no Helm value can switch Enterprise features on. Without a licence, every admin tab offers <strong>Get enterprise license</strong>, which opens a checkout for billing email, organisation and seats, and <strong>Retrieve license</strong> for a licence already paid but not yet activated.</p><p>With a licence, every user who signs in gets a seat automatically; untick it to free the seat. The instance reports its seat count to the licence service, which also renews the licence token. Only an aggregate user count is sent. <strong>Last check-in</strong> shows the most recent successful report.</p><h3 id="check-renewal-health" tabindex="-1">Check renewal health <a class="header-anchor" href="#check-renewal-health" aria-label="Permalink to &quot;Check renewal health&quot;">​</a></h3><p>Open <strong>Settings → License</strong> as an admin. For an activated licence the card shows:</p><ul><li><strong>Last successful report</strong>, or <strong>never</strong> before the first successful renewal.</li><li><strong>Enterprise features stop without renewal</strong>, the expiry of the currently verified token.</li><li><strong>Last report error</strong>, with its timestamp, or <strong>none</strong>. Errors remain visible across backend restarts and are cleared when a renewal succeeds.</li></ul><p>A warning appears seven days before the token expires and remains after expiry. Operators can change the lead time with <code>ee.license.reportWarningDays</code> (0–365, default 7). Zero warns only at expiry. This setting affects the warning, not licence validity or the reporting schedule. Reporting normally runs every 24 hours (<code>ee.license.reportIntervalHours</code>), starting about 30 seconds after the backend starts. Opening the page or <strong>Refresh license status</strong> reloads the status; the page does not send a report or continuously poll. No external notification is sent.</p><p>If reporting fails, restore backend connectivity to the licence service and check your subscription under <strong>Billing &amp; invoices</strong>. A rejected report shows its HTTP status; a request failure means connectivity or service availability needs checking. Invalid or missing renewal tokens leave the previous token in place. A successful renewal clears the error and moves the stop date according to the new signed token. Restart the backend to retry before its next scheduled report if needed.</p><p>The stop date is distinct from a scheduled cancellation or a plan end date: it is when Enterprise features stop if no further renewal succeeds. It is read from the signed token, not calculated as 45 days after the last report. Community features remain available after expiry, and admins can still inspect and activate a licence without an Enterprise entitlement.</p><h2 id="usage-limits" tabindex="-1">Usage limits <a class="header-anchor" href="#usage-limits" aria-label="Permalink to &quot;Usage limits&quot;">​</a></h2><p>Admins can set a monthly API budget for everyone (<strong>Global limit</strong>), for a group, or for a single user. The strictest limit that applies wins, and personal limits still apply. Details are on <a href="/docs/usage#organisation-wide-limits">Usage and cost</a>.</p><h2 id="groups-from-the-oidc-token" tabindex="-1">Groups from the OIDC token <a class="header-anchor" href="#groups-from-the-oidc-token" aria-label="Permalink to &quot;Groups from the OIDC token&quot;">​</a></h2><p>With Enterprise, the hub reads each user&#39;s groups from the access token at sign-in. The claim is <code>groups</code> by default. A leading <code>/</code> in a group path is dropped, so <code>/team/platform</code> is stored as <code>team/platform</code>.</p><p>Under <strong>Usage limits &amp; groups → Groups &amp; roles</strong>, groups appear once a member has signed in. Map a group to <strong>admin</strong> or <strong>user</strong>, or type a group name nobody has signed in with yet and click <strong>Map</strong>. Its first member is then an admin from their first request. Groups are also used for group limits, for project shares (see <a href="/docs/sharing">Sharing</a>) and for sharing skills and MCP servers.</p><p>Not tested: group membership was seeded in tests, not read from a real OIDC provider.</p><h2 id="allowed-agents" tabindex="-1">Allowed agents <a class="header-anchor" href="#allowed-agents" aria-label="Permalink to &quot;Allowed agents&quot;">​</a></h2><p><strong>Usage limits &amp; groups → Allowed agents</strong> restricts which agents (Claude, Codex, Cursor, OpenClaw, OpenCode) can be used for new sessions. Leave every box unticked for no restriction. A session with an agent that is not allowed is refused on create, edit, start, resume and duplicate, with a message to ask an administrator. Without a valid licence, every agent is allowed.</p><h2 id="operator-settings" tabindex="-1">Operator settings <a class="header-anchor" href="#operator-settings" aria-label="Permalink to &quot;Operator settings&quot;">​</a></h2><p>Some admin matters are chart values, not UI settings: <code>ee.admins</code>, <code>ee.billingPortalUrl</code>, and the Slack integration (<code>ee.slack.*</code>). See <a href="/docs/chart-values">Chart values</a> and <a href="/docs/slack">Slack</a>.</p>`,42)])])}const u=t(r,[["render",i]]);export{p as __pageData,u as default};
